1	package netdiag
2	
3	import (
4		"net/url"
5		"slices"
6		"strings"
7		"testing"
8	
9		"github.com/charmbracelet/x/ansi"
10	
11		"github.com/anthnel/devdesk/internal/netcheck"
12		"github.com/anthnel/devdesk/internal/netproxy"
13		"github.com/anthnel/devdesk/internal/ui/testutil"
14	)
15	
16	// DEVDESK-582, acceptance criteria 1, 2, 3, 4 and 6 at the screen level: the
17	// Proxy row says, in the table and in its detail, whether a proxy variable
18	// applies to the target, and no credential ever reaches a screen.
19	
20	const (
21		secretUser = "s3cretUser"
22		secretPass = "s3cretPass"
23	)
24	
25	// proxyEnv is the counting env with a scripted answer to the proxy question,
26	// so no test reads the proxy variables of the machine it runs on.
27	type proxyEnv struct {
28		*countingEnv
29		https, http netproxy.Decision
30	}
31	
32	func (e proxyEnv) ProxyFor(u *url.URL) netproxy.Decision {
33		e.countingEnv.ProxyFor(u)
34		if u.Scheme == "https" {
35			return e.https
36		}
37		return e.http
38	}
39	
40	// runWithProxyAnswer runs the whole pipeline through the model's messages with
41	// the given proxy answer for both schemes.
42	func runWithProxyAnswer(t *testing.T, answer netproxy.Decision) *Model {
43		t.Helper()
44		return runWithProxyAnswers(t, answer, answer)
45	}
46	
47	// runWithProxyAnswers answers the https and the http question separately.
48	func runWithProxyAnswers(t *testing.T, https, http netproxy.Decision) *Model {
49		t.Helper()
50		env := proxyEnv{countingEnv: newCountingEnv(), https: https, http: http}
51		m := newTestModel(t)
52		m.checkEnv = func(netcheck.Settings) netcheck.Env { return env }
53		return runDiagnostics(t, m, "127.0.0.1")
54	}
55	
56	// openProxyRow puts the cursor on the Proxy row and opens its detail.
57	func openProxyRow(t *testing.T, m *Model) *Model {
58		t.Helper()
59		for i, c := range m.checksTable.Visible() {
60			if c.ID == netcheck.CheckProxy {
61				m.checksTable.SetCursor(i)
62				m = feed(t, m, testutil.Key("enter"))
63				if m.state != StateDetails || m.selected.ID != netcheck.CheckProxy {
64					t.Fatalf("state = %v, selected = %q, want the Proxy detail open", m.state, m.selected.ID)
65				}
66				return m
67			}
68		}
69		t.Fatal("the table has no Proxy row")
70		return m
71	}
72	
73	// proxyLine is the table line that carries the Proxy row, stripped of styling.
74	func proxyLine(t *testing.T, rendered string) string {
75		t.Helper()
76		for _, line := range strings.Split(ansi.Strip(rendered), "\n") {
77			if strings.Contains(line, "Proxy") {
78				return line
79			}
80		}
81		t.Fatalf("no table line carries the Proxy row:\n%s", ansi.Strip(rendered))
82		return ""
83	}
84	
85	func noSecret(t *testing.T, where, text string) {
86		t.Helper()
87		for _, bad := range []string{secretUser, secretPass} {
88			if strings.Contains(text, bad) {
89				t.Errorf("%s carries %q:\n%s", where, bad, ansi.Strip(text))
90			}
91		}
92	}
93	
94	// Criterion 1 and 6: a proxied target reads "Configured for this target:
95	// host:port" in the table and the proxy in the detail, and no credential shows
