1	package netproxy
2	
3	import (
4		"net"
5		"net/netip"
6		"net/url"
7		"os"
8		"regexp"
9		"strings"
10		"unicode"
11		"unicode/utf8"
12	)
13	
14	// DecisionKind says what the proxy environment variables mean for one URL.
15	type DecisionKind int
16	
17	const (
18		// DecisionNone: no variable is set for this URL's scheme. It is the zero
19		// value, so an unfilled Decision reads as "no proxy".
20		DecisionNone DecisionKind = iota
21		// DecisionProxied: a proxy carries this URL.
22		DecisionProxied
23		// DecisionExcluded: a valid variable is set and NO_PROXY names the target.
24		DecisionExcluded
25		// DecisionLoopback: a valid variable is set, but Go never proxies
26		// localhost or a loopback address.
27		DecisionLoopback
28		// DecisionInvalid: the variable is set and is not a usable proxy URL.
29		DecisionInvalid
30	)
31	
32	// Decision is what Describe found out about one URL. It carries no credential:
33	// Proxy is Display's output and an invalid value is named by its variable only.
34	type Decision struct {
35		Kind DecisionKind
36		// Variable is the name of the variable read for the URL's scheme, with the
37		// case it was read in (HTTPS_PROXY or https_proxy); empty for None.
38		Variable string
39		// Proxy is Display(proxy) when Kind is DecisionProxied, empty otherwise.
40		Proxy string
41	}
42	
43	// Describe reports which proxy, if any, applies to u in the process
44	// environment. The answer comes from FromEnvironment, the function every
45	// DevDesk client uses; only the variable's name and validity are read here.
46	func Describe(u *url.URL) Decision {
47		return describe(u, os.Getenv, FromEnvironment)
48	}
49	
50	// describe is Describe with its inputs injected. sel is not consulted when the
51	// variables alone settle the answer (None, Invalid), so it may be nil then.
52	func describe(u *url.URL, getenv func(string) string, sel Selector) Decision {
53		var names [2]string
54		switch strings.ToLower(u.Scheme) {
55		case "https":
56			names = [2]string{"HTTPS_PROXY", "https_proxy"}
57		case "http":
58			names = [2]string{"HTTP_PROXY", "http_proxy"}
59		default:
60			return Decision{}
61		}
62		// The first non-empty name wins, like Go's getEnvAny.
63		name, value := "", ""
64		for _, n := range names {
65			if v := getenv(n); v != "" {
66				name, value = n, v
67				break
68			}
69		}
70		if name == "" {
71			return Decision{}
72		}
73		if !usableProxyValue(value) {
74			return Decision{Kind: DecisionInvalid, Variable: name}
75		}
76		proxy, err := sel(u)
77		if err != nil {
78			// The error text can quote the proxy URL, credentials included.
79			return Decision{Kind: DecisionInvalid, Variable: name}
80		}
81		if proxy != nil {
82			return Decision{Kind: DecisionProxied, Variable: name, Proxy: Display(proxy)}
83		}
84		// A nil proxy with a valid variable: Go skips a loopback target whatever
85		// NO_PROXY says, otherwise NO_PROXY named it.
86		if isLoopbackHost(u.Hostname()) {
87			return Decision{Kind: DecisionLoopback, Variable: name}
88		}
89		return Decision{Kind: DecisionExcluded, Variable: name}
90	}
91	
92	// explicitScheme matches a value that starts with a URL scheme, as opposed to
93	// one that only has "://" somewhere in its path or query.
94	var explicitScheme = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*://`)
95	
96	// usableProxyValue follows Go's parseProxy (url.Parse, then a retry with
97	// "http://" in front for a value without a scheme) and is stricter on three
98	// points, because Go ignores an unusable value and FromEnvironment alone
99	// cannot tell it from "no proxy":
100	//   - the host must not be empty;
101	//   - a value holding "@" must end up with userinfo, otherwise the credential
102	//     was mangled (an unescaped "/", "?" or "#" before the "@") and the text
103	//     before it became the host;
104	//   - the host must be printable UTF-8, since it ends up on screen.
105	func usableProxyValue(value string) bool {
106		explicit := explicitScheme.MatchString(value)
107		u, err := url.Parse(value)
108		switch {
109		case err != nil && explicit:
110			return false
111		case err == nil && u.Scheme != "" && u.Host != "":
112			// Parsed as written.
113		case err == nil && explicit:
114			// An explicit scheme with no host, such as "http://".
115			return false
116		default:
117			u, err = url.Parse("http://" + value)
118			if err != nil {
119				return false
120			}
121		}
122		if u.Host == "" || (u.User == nil && strings.Contains(value, "@")) {
123			return false
124		}
125		return isPrintable(u.Host)
126	}
127	
128	// isPrintable reports whether s is valid UTF-8 made of printable runes only.
129	func isPrintable(s string) bool {
130		if !utf8.ValidString(s) {
131			return false
132		}
133		for _, r := range s {
134			if !unicode.IsPrint(r) {
135				return false
136			}
137		}
138		return true
139	}
140	
141	// isLoopbackHost reports whether host is localhost or a loopback address.
142	func isLoopbackHost(host string) bool {
143		if strings.EqualFold(host, "localhost") {
144			return true
145		}
146		addr, err := netip.ParseAddr(host)
147		return err == nil && addr.Unmap().IsLoopback()
148	}
149	
150	// defaultPorts are the ports Display shows when the URL names none.
151	var defaultPorts = map[string]string{
152		"http":    "80",
153		"https":   "443",
154		"socks5":  "1080",
155		"socks5h": "1080",
156	}
157	
158	// Display renders a proxy URL as scheme://host:port and nothing else: never
159	// userinfo, path, query, fragment or IPv6 zone. It is the only way a proxy leaves this
160	// package for the screen. A scheme with no known default port shows no port
161	// unless the URL names one. Display(nil) is empty.
162	func Display(proxy *url.URL) string {
163		if proxy == nil {
164			return ""
165		}
166		port := proxy.Port()
167		if port == "" {
168			port = defaultPorts[strings.ToLower(proxy.Scheme)]
169		}
170		// The zone of a link-local address can be any text: drop it.
171		host, _, _ := strings.Cut(proxy.Hostname(), "%")
172		if port != "" {
173			host = net.JoinHostPort(host, port)
174		} else if strings.Contains(host, ":") {
175			host = "[" + host + "]"
176		}
177		return proxy.Scheme + "://" + host
178	}
